function drawCitadelEnemy(e){const c=citadelSprite(e.boss?'warden':e.role,e.boss||e.role==='scribe'||e.action||e.moveBlend>.1?Math.floor(weaponClock*(e.action?12:e.boss?3:7))%8:0,!!e.elite),flip=(e.facingAngle||0)>Math.PI/2||(e.facingAngle||0)<-Math.PI/2;shadow(e.x,e.y,e.boss?55:e.role==='hound'?30:23);ctx.save();ctx.translate(Math.round(e.x),Math.round(e.y));if(flip)ctx.scale(-1,1);if(e.action){const t=e.action.elapsed/e.action.windup;ctx.translate(0,Math.sin(Math.min(1,t)*Math.PI)*-3)}ctx.drawImage(c,-c.width/2,-(c.anchorY||c.height-18));ctx.restore();if(!e.boss){const visible=e.hit>0||e.action||Math.hypot(p.x-e.x,p.y-e.y)<280;if(visible){const w=e.elite?58:42;rect(e.x-w/2,e.y-90,w,5,'#101c28');rect(e.x-w/2+1,e.y-89,(w-2)*Math.max(0,e.hp/e.max),3,e.elite?'#d5b571':'#95b8a0');label((e.elite?'SEÇKİN · ':'')+CITADEL_ROLES[e.role].name,e.x,e.y-99,e.elite?'#ecd39a':'#bdcdbd',10)}}}
