drawSlash=function(x,y,s){if(!activeSwing)return;const t=activeSwing.elapsed/activeSwing.duration;if(t<.24||t>.65)return;const pose=swingPose(t,activeSwing.direction,activeSwing.combo),angle=pose.swordAngle-Math.PI/2,sign=activeSwing.combo?-1:1,r=s.range*.94,fade=Math.sin((t-.24)/.41*Math.PI);ctx.save();ctx.translate(x,y-25);ctx.globalCompositeOperation='lighter';if(p.sword==='lunar'){ctx.rotate(activeSwing.direction);ctx.fillStyle=s.edge;ctx.globalAlpha=fade*.8;ctx.beginPath();ctx.moveTo(12,-7);ctx.lineTo(r+20,0);ctx.lineTo(12,7);ctx.fill();ctx.strokeStyle=s.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(r+30,0);ctx.stroke()}else{for(let n=0;n<6;n++){ctx.strokeStyle=n<2?s.edge:s.color;ctx.globalAlpha=fade*(.75-n*.1);ctx.lineWidth=(activeSwing.chain===3?10:7)-n;ctx.beginPath();ctx.ellipse(0,0,r-n*4,(r-n*4)*.58,0,angle-sign*(1.1-n*.08),angle,sign<0);ctx.stroke()}ctx.globalAlpha=fade*.8;ctx.fillStyle=s.edge;for(let n=0;n<5;n++){const a=angle-sign*n*.17;ctx.fillRect(Math.cos(a)*r,Math.sin(a)*r*.58,3,3)}}ctx.restore()};
function drawEnemyTelegraph(e){if(!e.action||e.action.applied)return;const a=e.action,t=Math.min(1,a.elapsed/a.windup),boss=e.boss;ctx.save();ctx.translate(e.x,e.y-10);ctx.fillStyle=boss?'#e09a6540':'#c7896740';ctx.strokeStyle=boss?'#f0bd84':'#dfb58a';ctx.lineWidth=2;
 if(a.type==='slam'){ctx.translate(a.tx-e.x,a.ty-e.y+10);ctx.beginPath();ctx.arc(0,0,a.radius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,a.radius*.88,-Math.PI/2,-Math.PI/2+Math.PI*2*t);ctx.stroke()}
 else if(a.type==='ring'){ctx.beginPath();ctx.arc(0,0,210,0,7);ctx.arc(0,0,85,0,7,true);ctx.fill('evenodd');ctx.stroke();ctx.strokeStyle='#b6d0a4';ctx.beginPath();ctx.arc(0,0,76,0,7);ctx.stroke()}
 else if(a.type==='chain'||a.type==='pounce'||a.type==='bolt'){ctx.rotate(a.angle);const length=a.type==='chain'?290:a.type==='bolt'?280:170;ctx.fillRect(0,-20,length,40);ctx.strokeRect(0,-20,length,40);ctx.fillStyle='#f2ca8b';ctx.fillRect(0,-3,length*t,6)}else{const reach=boss?118:CITADEL_ROLES[e.role].reach,arc=boss?1.25:e.role==='root'?.28:e.role==='revenant'?1.3:1;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,reach,a.angle-arc,a.angle+arc);ctx.closePath();ctx.fill();ctx.stroke();ctx.globalAlpha=.75;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,reach*t,a.angle-arc,a.angle+arc);ctx.stroke()}ctx.restore()}
function drawCitadelEffects(){ctx.save();ctx.translate(-camera.x,-camera.y);for(const e of enemies)if(!e.dead&&dungeonRoomOpen(e.dungeonRoom))drawEnemyTelegraph(e);for(const b of citadelProjectiles){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.dy,b.dx));ctx.fillStyle='#e7a16d';ctx.fillRect(-12,-4,20,8);ctx.fillStyle='#ffe4a6';ctx.fillRect(-2,-3,10,6);ctx.restore()}for(const burst of citadelBursts){const t=1-burst.life/burst.max;if(burst.type==='death'){const c=citadelSprite(burst.role||'mite');ctx.save();ctx.globalAlpha=(1-t)*.5;ctx.translate(burst.x,burst.y);ctx.scale(1,1-t*.65);ctx.drawImage(c,-c.width/2,-(c.anchorY||c.height-18));ctx.restore();continue}ctx.globalAlpha=1-t;ctx.strokeStyle=burst.color;ctx.lineWidth=4*(1-t)+1;ctx.beginPath();if(burst.type==='enemyArc')ctx.ellipse(burst.x,burst.y,burst.r,burst.r*.55,0,burst.angle-1.1,burst.angle+1.1);else ctx.ellipse(burst.x,burst.y,burst.r*(.3+t),burst.r*(.3+t)*.6,0,0,7);ctx.stroke()}for(const s of citadelHitSparks){ctx.globalAlpha=Math.min(1,s.life/.12);ctx.fillStyle=s.color;ctx.fillRect(Math.round(s.x),Math.round(s.y),s.life>.15?3:2,s.life>.15?3:2)}if(dodgeAction){ctx.globalAlpha=.25;for(let n=1;n<4;n++){ctx.fillStyle='#b7d4c0';ctx.beginPath();ctx.ellipse(p.x-Math.cos(dodgeAction.angle)*n*14,p.y-Math.sin(dodgeAction.angle)*n*14,14,6,0,0,7);ctx.fill()}}ctx.restore()}
const drawBeforeCitadel=draw;draw=function(){drawBeforeCitadel();if(p.area==='forest'&&dungeonRun)drawCitadelEffects()};
